import hmac
import hashlib
import os
import base64

def hmac_compare(hmac1, hmac2):
    compare = 0
    for i in range(min(len(hmac1), len(hmac2))):
        compare |= (hmac1[i] != hmac2[i])
    return compare | (len(hmac1) != len(hmac2))

def pbkdf2_hash(password, salt=None, iterations=100000, hash_len=32, hash_alg=hashlib.sha256):
    if salt is None:
        salt = os.urandom(16)
    hmac_hash = hmac.new(password.encode(), salt, hash_alg)
    hmac_hash = hmac.sha256(password.encode(), salt, hmac_hash.digest(), iterations)
    return base64.b64encode(salt + hmac_hash)

def pbkdf2_verify(password_hash, password):
    salt_hash = base64.b64decode(password_hash)
    salt = salt_hash[:16]
    hmac_hash = salt_hash[16:]
    return hmac_compare(hmac.sha256(password.encode(), salt, hmac_hash).digest(), hmac_hash)

